package dia8;

public class Ejercicio1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int i = 0;
		int suma = 0;
		while (i<100) { // variable que guardará el resultado de la suma
			i += 1; // contador 
			suma += i; // la variable suma guarda el valor de suma + i, Acumulador
		}
		System.out.println(suma);
	}

}
